package mx.com.mesaregia.logistica.api.controller; import jakarta.validation.Valid; import mx.com.mesaregia.logistica.api.request.*; import mx.com.mesaregia.logistica.api.response.EtapaResponse; import mx.com.mesaregia.logistica.application.service.EtapaLogisticaService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/logistica") public class EtapaController {private final EtapaLogisticaService s;public EtapaController(EtapaLogisticaService s){this.s=s;} @GetMapping("/programaciones/{id}/etapas") @PreAuthorize("hasAnyAuthority('logistica.consultar','logistica.gestionar')") public List<EtapaResponse> listar(@PathVariable Long id){return s.listarPorProgramacion(id);} @PostMapping("/etapas/{id}/iniciar") @PreAuthorize("hasAnyAuthority('logistica.proceso.gestion','logistica.traslado')") public EtapaResponse iniciar(@PathVariable Long id,@Valid @RequestBody EtapaIniciarRequest r){return s.iniciar(id,r);} @PatchMapping("/etapas/{id}/avance") @PreAuthorize("hasAuthority('logistica.proceso.gestion')") public EtapaResponse avance(@PathVariable Long id,@Valid @RequestBody EtapaAvanceRequest r){return s.avance(id,r);} @PostMapping("/etapas/{id}/evidencias") @PreAuthorize("hasAnyAuthority('logistica.proceso.gestion','logistica.traslado')") public EtapaResponse evidencias(@PathVariable Long id,@Valid @RequestBody EtapaEvidenciaRequest r){return s.evidencias(id,r);} @PostMapping("/etapas/{id}/confirmar") @PreAuthorize("hasAnyAuthority('logistica.proceso.gestion','logistica.traslado')") public EtapaResponse confirmar(@PathVariable Long id,@Valid @RequestBody EtapaConfirmarRequest r){return s.confirmar(id,r);} }
